FUNCTION_BLOCK FB
VAR_INPUT
    recipe      : ARRAY[1..8] OF ST_Recipe;
    selSlot     : INT;
    loadCmd     : BOOL;
    running     : BOOL;
END_VAR
VAR_OUTPUT
    valid       : BOOL;
    loadedID    : INT;
END_VAR
VAR
    prevLoadCmd : BOOL := FALSE;
END_VAR

// 边沿检测：loadCmd上升沿时触发装载
IF loadCmd AND NOT prevLoadCmd AND NOT running THEN
    // 槽位越界检查（必须先检查，防止数组越界）
    IF (selSlot < 1) OR (selSlot > 8) THEN
        valid    := FALSE;
        loadedID := 0;
    ELSE
        // 取当前选中槽位数据到临时变量，避免重复访问数组
        curRecipeID     := recipe[selSlot].recipeID;
        curTotalRatio   := recipe[selSlot].totalRatio;
        curTemperature  := recipe[selSlot].temperature;

        // 配方校验（全部满足才算valid）
        IF (curRecipeID = 0)
            OR (curTotalRatio < 99.0)
            OR (curTotalRatio > 101.0)
            OR (curTemperature < 30.0)
            OR (curTemperature > 180.0) THEN
            valid    := FALSE;
            loadedID := 0;
        ELSE
            valid    := TRUE;
            loadedID := curRecipeID;
        END_IF
    END_IF
END_IF

// 更新边沿检测历史值
prevLoadCmd := loadCmd;

END_FUNCTION_BLOCK
